SELECT percentile_cont(0.75) within GROUP (ORDER BY AVG(value)) AS seventy_five_percentile FROM labevents JOIN patients ON labevents.subject_id = patients.subject_id JOIN admissions ON patients.subject_id = admissions.subject_id WHERE patients.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) = 67 AND d_labitems.label = 'Serum glucose' AND (labevents.charttime - admissions.admittime) <= 24;